def solve(grid):
    # Find the line color (the non‑zero colour that forms the grid lines)
    from collections import Counter
    flat = [v for row in grid for v in row]
    cnt = Counter(flat)
    # the most common non‑zero colour is the line colour
    line_color = max((c for c in cnt if c != 0), key=lambda x: cnt[x])

    H = len(grid)
    W = len(grid[0])

    # ----- detect vertical lines -----
    vertical_lines = []
    for c in range(W):
        if sum(1 for r in range(H) if grid[r][c] == line_color) > H // 2:
            vertical_lines.append(c)
    # ----- detect horizontal lines -----
    horizontal_lines = []
    for r in range(H):
        if sum(1 for c in range(W) if grid[r][c] == line_color) > W // 2:
            horizontal_lines.append(r)

    # mapping from column/row to region index (0 … number_of_regions)
    # region index = number of vertical lines to the left of the column
    def col_region(c):
        return sum(1 for v in vertical_lines if v < c)

    def row_region(r):
        return sum(1 for h in horizontal_lines if h < r)

    num_col_regions = len(vertical_lines) + 1
    num_row_regions = len(horizontal_lines) + 1

    # ----- holes in each horizontal line -----
    holes_in_line = {line: [] for line in horizontal_lines}
    for r in horizontal_lines:
        for c in range(W):
            if grid[r][c] != line_color:
                holes_in_line[r].append(col_region(c))

    # ----- decide colour for each cell -----
    out_grid = [[0] * W for _ in range(H)]

    for r in range(H):
        for c in range(W):
            if grid[r][c] == line_color:
                out_grid[r][c] = line_color
                continue

            # region indices
            icol = col_region(c)
            irow = row_region(r)

            # obtain the holes of the lines that bound this band
            if irow == 0:                     # topmost band
                top_holes = []
                bottom_holes = holes_in_line.get(horizontal_lines[0], [])
            elif irow == num_row_regions - 1: # bottommost band
                top_holes = holes_in_line.get(horizontal_lines[-1], [])
                bottom_holes = []
            else:
                top_holes = holes_in_line.get(horizontal_lines[irow - 1], [])
                bottom_holes = holes_in_line.get(horizontal_lines[irow], [])

            # special handling for the second‑to‑last band
            if irow == num_row_regions - 2:
                # choose the line that has exactly one hole (if any)
                chosen = None
                if top_holes and (not bottom_holes or len(bottom_holes) != 1):
                    if len(top_holes) == 1:
                        chosen = top_holes[0]
                elif bottom_holes:
                    if len(bottom_holes) == 1:
                        chosen = bottom_holes[0]
                if chosen is None:
                    # more than one hole – fill everything with 4
                    col = 4
                else:
                    # neighbour towards the centre
                    if chosen == 0:
                        neighbour = 1
                    elif chosen == num_col_regions - 1:
                        neighbour = chosen - 1
                    else:
                        centre = num_col_regions // 2
                        neighbour = chosen + 1 if chosen < centre else chosen - 1
                    if icol == chosen:
                        col = 4
                    elif icol == neighbour:
                        col = 3
                    else:
                        col = 4
            else:
                # generic cases
                if top_holes and bottom_holes:
                    col = 4
                elif not top_holes and not bottom_holes:
                    col = 3
                else:
                    # exactly one of the two lines has holes
                    holes = top_holes if top_holes else bottom_holes
                    if len(holes) > 1:
                        col = 4
                    else:
                        h = holes[0]
                        if icol == h:
                            col = 4
                        else:
                            col = 3

            out_grid[r][c] = col

    return out_grid

